const cfg = $('Set RFM Config1').first().json;
const orders = $('Fetch Shopify Orders (24 Months)1').all().flatMap(i => i.json.body?.orders || i.json.orders || [])
  .filter(o => o.customer?.id && !o.cancelled_at && !/refunded|voided/i.test(o.financial_status || ''));
const prevRows = $('Read Previous Segments1').all().map(i => i.json).filter(r => r.customer_id);
const prev = Object.fromEntries(prevRows.map(r => [String(r.customer_id), r.segment]));
const hash = s => { let h = 0; for (const ch of String(s)) h = (h * 31 + ch.charCodeAt(0)) >>> 0; return h % 100; };
const now = Date.now();
const C = {};
for (const o of orders) {
  const id = String(o.customer.id);
  const c = C[id] = C[id] || { customer_id: id, first_name: o.customer.first_name || '', email: (o.customer.email || o.email || '').toLowerCase(),
    phone: String(o.customer.phone || o.phone || '').replace(/\D/g, ''), tags: o.customer.tags || '',
    email_ok: o.customer.email_marketing_consent?.state === 'subscribed' || o.customer.accepts_marketing === true,
    wa_ok: o.customer.sms_marketing_consent?.state === 'subscribed' || /whatsapp-optin/i.test(o.customer.tags || ''),
    orders: 0, spend: 0, last: 0, first: Infinity, cats: {} };
  const t = new Date(o.created_at).getTime();
  c.orders++; c.spend += Number(o.total_price) || 0; c.last = Math.max(c.last, t); c.first = Math.min(c.first, t);
  for (const li of o.line_items || []) { const cat = (li.product_type || li.vendor || String(li.title || '').split(' ').slice(-1)[0] || 'Other').trim();
    c.cats[cat] = (c.cats[cat] || 0) + (Number(li.price) || 0) * (li.quantity || 1); }
}
const list = Object.values(C).map(c => ({ ...c, recency_days: Math.floor((now - c.last) / 864e5), spend: Math.round(c.spend),
  fav_category: Object.entries(c.cats).sort((a, b) => b[1] - a[1])[0]?.[0] || 'Other', aov: Math.round(c.spend / c.orders) }));
// quintile scores (5 = best)
const quint = (arr, key, higherBetter) => { const s = [...arr].sort((a, b) => higherBetter ? a[key] - b[key] : b[key] - a[key]);
  s.forEach((c, i) => c[key + '_score'] = Math.min(5, Math.floor(i / s.length * 5) + 1)); };
quint(list, 'recency_days', false); quint(list, 'orders', true); quint(list, 'spend', true);
const seg = (r, f, m) =>
  r >= 4 && f >= 4 && m >= 4 ? 'Champions' : r <= 2 && f >= 4 && m >= 4 ? (r === 1 ? "Can't Lose Them" : 'At Risk')
  : r <= 2 && f >= 3 ? 'At Risk' : f >= 4 && r >= 3 ? 'Loyal' : r >= 4 && f >= 2 ? 'Potential Loyalist'
  : r === 5 && f === 1 ? 'New Customers' : r === 4 && f === 1 ? 'Promising' : r === 3 && f >= 3 ? 'Need Attention'
  : r === 3 ? 'About to Sleep' : r === 1 && f <= 1 ? 'Lost' : 'Hibernating';
list.forEach(c => { c.R = c.recency_days_score; c.F = c.orders_score; c.M = c.spend_score; c.rfm = `${c.R}${c.F}${c.M}`;
  c.segment = seg(c.R, c.F, c.M); c.prev_segment = prev[c.customer_id] || 'new'; c.holdout = hash(c.customer_id + c.segment) < cfg.holdout_pct; });
// ---- lift of LAST week's offers: treated vs holdout conversion since last run
const lastOrder = Object.fromEntries(list.map(c => [c.customer_id, c.last]));
const lift = {};
prevRows.filter(p => p.offer_code !== undefined && p.updated_at).forEach(p => {
  const L = lift[p.segment] = lift[p.segment] || { t: 0, tc: 0, h: 0, hc: 0 };
  const conv = (lastOrder[String(p.customer_id)] || 0) > new Date(p.updated_at).getTime();
  if (String(p.holdout) === 'true') { L.h++; if (conv) L.hc++; } else if (p.offer_code) { L.t++; if (conv) L.tc++; }
});
const liftRows = Object.entries(lift).filter(([, L]) => L.t >= 5 && L.h >= 3).map(([seg, L]) => { const tr = L.tc / L.t, hr = L.hc / L.h;
  return { segment: seg, treated: L.t, treated_conv_pct: Math.round(tr * 1000) / 10, holdout: L.h, holdout_conv_pct: Math.round(hr * 1000) / 10, lift_pp: Math.round((tr - hr) * 1000) / 10 }; });
const segs = {};
list.forEach(c => { const s = segs[c.segment] = segs[c.segment] || { segment: c.segment, customers: 0, revenue: 0, recency: 0, orders: 0, cats: {}, email: 0, wa: 0 };
  s.customers++; s.revenue += c.spend; s.recency += c.recency_days; s.orders += c.orders; s.cats[c.fav_category] = (s.cats[c.fav_category] || 0) + 1;
  if (c.email_ok && c.email) s.email++; if (c.wa_ok && c.phone) s.wa++; });
const stats = Object.values(segs).map(s => ({ segment: s.segment, customers: s.customers, revenue: s.revenue, avg_recency_days: Math.round(s.recency / s.customers),
  avg_orders: Math.round(s.orders / s.customers * 10) / 10, aov: Math.round(s.revenue / Math.max(1, s.orders)),
  top_categories: Object.entries(s.cats).sort((a, b) => b[1] - a[1]).slice(0, 4).map(x => x[0]), reachable_email: s.email, reachable_wa: s.wa }))
  .sort((a, b) => b.revenue - a.revenue);
const moves = {};
list.filter(c => c.prev_segment !== 'new' && c.prev_segment !== c.segment).forEach(c => { const k = `${c.prev_segment} → ${c.segment}`; moves[k] = (moves[k] || 0) + 1; });
const atRisk = list.filter(c => ['At Risk', "Can't Lose Them", 'About to Sleep'].includes(c.segment));
return [{ json: { customers: list.map(({ cats, first, last, ...c }) => c), stats,
  transitions: Object.entries(moves).sort((a, b) => b[1] - a[1]).slice(0, 8), orders_analysed: orders.length,
  revenue_at_risk: atRisk.reduce((a, c) => a + c.spend, 0), at_risk_customers: atRisk.length, lift: liftRows, week: $now.toFormat("kkkk-'W'WW") } }];

const cfg = $('Set RFM Config1').first().json;
const r = $input.first().json;
return r.stats.filter(s => cfg.target_segments.includes(s.segment) && s.customers >= cfg.min_segment_size)
  .map(s => ({ json: { ...s, cap_pct: cfg.caps[s.segment] ?? 10, store: cfg.store_name, offer_days: cfg.offer_days, min_order_value: cfg.min_order_value } }));

const s = $('Split Target Segments1').item.json;
const cfg = $('Set RFM Config1').first().json;
const ai = $json.message?.content || {};
const pct = Math.max(0, Math.min(Number(ai.discount_pct) || 0, s.cap_pct));
const slug = s.segment.toUpperCase().replace(/[^A-Z]/g, '').slice(0, 6);
const code = `${slug}${$now.toFormat('WW')}${Math.random().toString(36).slice(2, 6).toUpperCase()}`;
const starts = $now.toISO(), ends = $now.plus({ days: cfg.offer_days }).endOf('day').toISO();
const common = { title: `RFM ${s.segment} W${$now.toFormat('WW')}`, code, startsAt: starts, endsAt: ends, customerSelection: { all: true },
  appliesOncePerCustomer: true, minimumRequirement: { subtotal: { greaterThanOrEqualToSubtotal: String(cfg.min_order_value) } } };
const body = pct > 0
  ? { query: 'mutation($d: DiscountCodeBasicInput!){ discountCodeBasicCreate(basicCodeDiscount:$d){ codeDiscountNode{ id } userErrors{ field message } } }',
      variables: { d: { ...common, customerGets: { value: { percentage: pct / 100 }, items: { all: true } } } } }
  : { query: 'mutation($d: DiscountCodeFreeShippingInput!){ discountCodeFreeShippingCreate(freeShippingCodeDiscount:$d){ codeDiscountNode{ id } userErrors{ field message } } }',
      variables: { d: { ...common, destination: { all: true } } } };
return { json: { segment: s.segment, customers: s.customers, discount_pct: pct, ai_requested_pct: Number(ai.discount_pct) || 0, offer_code: code,
  offer_label: pct > 0 ? `${pct}% off` : 'Free shipping + early access', expires: $now.plus({ days: cfg.offer_days }).toFormat('dd LLL'),
  copy: { ...ai, discount_pct: pct }, shopify_body: body } };

const offers = $('Apply Offer Guardrails1').all().map((it, i) => {
  const r = $input.all()[i]?.json || {};
  const d = r.body?.data || {};
  const res = d.discountCodeBasicCreate || d.discountCodeFreeShippingCreate;
  const errs = [...(res?.userErrors || []).map(e => e.message), ...(r.body?.errors || []).map(e => e.message || e)];
  const { shopify_body, ...o } = it.json;
  return { ...o, code_ok: r.statusCode === 200 && !!res?.codeDiscountNode && !errs.length, code_error: errs.join('; ') };
});
return [{ json: { offers } }];

const cfg = $('Set RFM Config1').first().json;
const r = $('Score RFM & Segment1').first().json;
const offers = Object.fromEntries($input.first().json.offers.filter(o => o.code_ok).map(o => [o.segment, o]));
const jobs = [];
for (const [seg, o] of Object.entries(offers)) {
  const list = cfg.klaviyo_lists[seg];
  const people = r.customers.filter(c => c.segment === seg && c.email_ok && c.email && !c.holdout);
  if (!list || !people.length) continue;
  for (let i = 0; i < people.length; i += 10000) jobs.push({ json: { segment: seg, count: Math.min(10000, people.length - i), body: { data: { type: 'profile-bulk-import-job',
    attributes: { profiles: { data: people.slice(i, i + 10000).map(c => ({ type: 'profile', attributes: { email: c.email, first_name: c.first_name,
      ...(c.phone ? { phone_number: '+' + c.phone } : {}),
      properties: { rfm_segment: seg, rfm_score: c.rfm, rfm_week: r.week, winback_offer: o.offer_label, winback_code: o.offer_code, winback_expires: o.expires,
        winback_subject: o.copy.email_subject, winback_preview: o.copy.email_preview, winback_body: o.copy.email_body_html,
        fav_category: c.fav_category, lifetime_spend_inr: c.spend, orders_count: c.orders, days_since_last_order: c.recency_days } } })) } },
    relationships: { lists: { data: [{ type: 'list', id: list }] } } } } } });
}
return jobs;

const cfg = $('Set RFM Config1').first().json;
const r = $('Score RFM & Segment1').first().json;
const offers = Object.fromEntries($input.first().json.offers.filter(o => o.code_ok).map(o => [o.segment, o]));
const priority = ["Can't Lose Them", 'At Risk', 'Lost', 'Hibernating', 'About to Sleep', 'Need Attention', 'Potential Loyalist', 'New Customers', 'Champions'];
return r.customers.filter(c => offers[c.segment] && !c.holdout && c.wa_ok && c.phone && c.phone.length >= 10)
  .sort((a, b) => priority.indexOf(a.segment) - priority.indexOf(b.segment) || b.spend - a.spend).slice(0, cfg.wa_daily_cap)
  .map(c => { const o = offers[c.segment];
    const hook = (o.copy.category_hooks || {})[c.fav_category] || o.copy.whatsapp_hook_default || `We picked something new for you at ${cfg.store_name}.`;
    return { json: { customer_id: c.customer_id, segment: c.segment, phone: c.phone, code: o.offer_code, body: { messaging_product: 'whatsapp', to: c.phone, type: 'template',
      template: { name: cfg.wa_template, language: { code: cfg.wa_lang }, components: [{ type: 'body', parameters: [
        { type: 'text', text: c.first_name || 'there' }, { type: 'text', text: String(hook).slice(0, 90) },
        { type: 'text', text: o.offer_code }, { type: 'text', text: o.expires }] }] } } } }; });

const r = $('Score RFM & Segment1').first().json;
const offers = Object.fromEntries($input.first().json.offers.map(o => [o.segment, o]));
return r.customers.map(c => ({ json: { customer_id: c.customer_id, email: c.email, phone: c.phone, first_name: c.first_name, segment: c.segment,
  prev_segment: c.prev_segment, rfm: c.rfm, recency_days: c.recency_days, orders: c.orders, spend: c.spend, aov: c.aov, fav_category: c.fav_category,
  holdout: c.holdout, offer_code: offers[c.segment]?.code_ok && !c.holdout ? offers[c.segment].offer_code : '', week: r.week, updated_at: new Date().toISOString() } }));

const r = $('Score RFM & Segment1').first().json;
const offers = $input.first().json.offers;
const inr = v => '₹' + Math.round(v).toLocaleString('en-IN');
const lines = [`:bar_chart: *RFM report ${r.week}* · ${r.customers.length} customers · ${r.orders_analysed} orders (24 months)`,
  `:warning: Revenue at risk (At Risk + Can't Lose + About to Sleep): *${inr(r.revenue_at_risk)}* across ${r.at_risk_customers} customers`, '',
  '*Segments*', ...r.stats.map(s => `• ${s.segment}: ${s.customers} · ${inr(s.revenue)} · ${s.avg_recency_days}d since last · AOV ${inr(s.aov)} · reach ✉️${s.reachable_email} 💬${s.reachable_wa}`),
  '', '*Biggest moves this week*', ...(r.transitions.length ? r.transitions.map(([k, v]) => `• ${k}: ${v}`) : ['• first run – no history yet']),
  '', '*Last week\'s offer lift (treated vs 10% holdout)*', ...(r.lift.length ? r.lift.map(l => `• ${l.segment}: ${l.treated_conv_pct}% vs ${l.holdout_conv_pct}% → ${l.lift_pp >= 0 ? '+' : ''}${l.lift_pp} pp (n=${l.treated}/${l.holdout})`) : ['• not enough data yet']),
  '', '*Offers launched*', ...offers.map(o => `• ${o.segment}: ${o.offer_label} · \`${o.offer_code}\` till ${o.expires}${o.code_ok ? '' : ' :x: ' + o.code_error}${o.ai_requested_pct > o.discount_pct ? ` (AI asked ${o.ai_requested_pct}%, capped)` : ''}`)];
return [{ json: { text: lines.join('\n').slice(0, 3900) } }];

const sends = $('Build WhatsApp Sends1').all().map(i => i.json);
return $input.all().map((it, i) => ({ json: { week: $('Score RFM & Segment1').first().json.week, customer_id: sends[i]?.customer_id, segment: sends[i]?.segment,
  channel: 'whatsapp', code: sends[i]?.code, status: it.json.statusCode === 200 ? 'sent' : `failed ${it.json.statusCode}`,
  message_id: it.json.body?.messages?.[0]?.id || '', error: it.json.body?.error?.message || '', ts: new Date().toISOString() } }));
